  .jy-calendar-entry[data-near] .jy-event-state { background: #dbe5cc; color: #3c583b; }
  .jy-status .jy-calendar-body .jy-forum-edition { display: inline-flex; align-items: center; gap: 7px; margin: 0; color: #76482f; font-size: 13px; font-weight: 750; }
  .jy-forum-edition span { width: 7px; height: 7px; border-radius: 50%; background: #a55a3e; }
  .jy-forum-toolbar { border-bottom: 2px solid #8e523b; padding-bottom: 8px; }
  /* 拟真微信朋友圈/班群流 */
  .jy-status .jy-feed {
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin: 0;
    padding: 6px 0 10px;
    list-style: none;
  }
  .jy-feed li {
    display: grid;
    grid-template-columns: 36px minmax(0, 1fr);
    gap: 10px;
    padding: 10px 12px;
    border-radius: 10px;
    background: #ffffff;
    border: 1px solid #e7ded0;
    box-shadow: 0 2px 6px rgba(60, 48, 32, 0.04);
    overflow-wrap: anywhere;
  }
  .jy-moment-avatar {
    width: 36px;
    height: 36px;
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 15px;
    font-weight: 800;
    color: #ffffff;
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.12);
    user-select: none;
    flex-shrink: 0;
  }
  .jy-moment-box {
    display: flex;
    flex-direction: column;
    min-width: 0;
  }
  .jy-feed-top {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-bottom: 3px;
    flex-wrap: wrap;
  }
  .jy-moment-user {
    font-size: 13.5px;
    font-weight: 750;
    color: #3b597b;
    letter-spacing: 0.2px;
  }
  .jy-feed-tag {
    padding: 1.5px 6px;
    border-radius: 4px;
    background: #e9ecef;
    color: #495057;
    font-size: 9.5px;
    font-weight: 700;
  }
  .jy-feed-tag[data-channel="公告"] { background: #e3f2fd; color: #1565c0; }
  .jy-feed-tag[data-channel="班群"] { background: #e8f5e9; color: #2e7d32; }
  .jy-feed-tag[data-channel="朋友圈"] { background: #fce4ec; color: #c2185b; }
  .jy-feed-tag[data-channel="八卦"] { background: #fff3e0; color: #e65100; }
  .jy-feed-tag[data-channel="来信"] { background: #f3e5f5; color: #7b1fa2; }
  .jy-feed-tag[data-channel="趣事"] { background: #e0f7fa; color: #00838f; }
  .jy-feed-tag[data-channel="余波"] { background: #ffebee; color: #c62828; }
  .jy-feed-source {
    font-size: 10.5px;
    color: #8c857b;
  }
  .jy-feed strong, .jy-moment-title {
    display: block;
    margin: 2px 0 3px;
    font-size: 13.5px;
    font-weight: 800;
    color: #24332c;
    line-height: 1.4;
  }
  .jy-status .jy-feed p, .jy-moment-body {
    margin: 0 0 5px;
    font-size: 12.5px;
    line-height: 1.55;
    color: #3d3b38;
  }
  .jy-moment-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    font-size: 10.5px;
    color: #9e978e;
    margin-bottom: 4px;
  }
  .jy-feed small {
    color: #8c857b;
    font-size: 10.5px;
  }
  .jy-moment-interactions {
    margin-top: 4px;
    padding: 6px 8px;
    border-radius: 6px;
    background: #f7f6f2;
    border: 1px solid #eee7db;
    display: flex;
    flex-direction: column;
    gap: 4px;
    font-size: 11px;
    position: relative;
  }
  .jy-moment-interactions::before {
    content: "";
    position: absolute;
    top: -5px;
    left: 12px;
    border-left: 5px solid transparent;
    border-right: 5px solid transparent;
    border-bottom: 5px solid #eee7db;
  }
  .jy-moment-likes {
    color: #4a6fa5;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 4px;
    padding-bottom: 3px;
    border-bottom: 1px solid #e8e2d5;
    line-height: 1.35;
  }
  .jy-moment-likes::before {
    content: "♡";
    font-size: 12px;
    color: #e57373;
    font-weight: bold;
  }
  .jy-moment-comment {
    line-height: 1.4;
    color: #333333;
    font-size: 11px;
  }
  .jy-comment-user {
    font-weight: 750;
    color: #4a6fa5;
    margin-right: 4px;
  }
  .jy-comment-text {
    color: #444444;
  }
  @media (max-width: 360px) {
    .jy-status .jy-readouts, .jy-status .jy-calendar-body { padding: 8px; }
    .jy-status .jy-calendar-entry { grid-template-columns: 35px minmax(0, 1fr) auto; gap: 5px; padding: 6px; }
  }

  /* 夜间笔记：仅改变界面外观，不触碰消息变量。 */
  .jy-theme-button { min-height: 34px; padding: 5px 9px; border: 1px solid #b8c9c1; border-radius: 9px; background: #fffdf7; color: #35574f; font: inherit; cursor: pointer; }
  .jy-status[data-theme="dark"] { --c-ink:#e2e9df; --c-muted:#aabcb2; --c-paper:#202a28; --c-panel:#293732; --c-line:#45594f; --c-primary:#9ed0bc; --c-accent:#f3aa87; --c-warm:#e3c77c; --c-cool:#a7c6ea; color-scheme:dark; color:var(--c-ink); }
  .jy-status[data-theme="dark"] :is(.jy-shell,.jy-readout,.jy-calendar-entry,.jy-feed li,.jy-person,.jy-album-card,.jy-avatar-card,.jy-photo-viewer-card,.jy-map-card,.jy-map-head) { background:#202d29; border-color:#45594f; color:#e2e9df; box-shadow:none; }
  .jy-status[data-theme="dark"] :is(.jy-head,.jy-scene-now,.jy-time,.jy-student-card.jy-me,.jy-moment-interactions,.jy-calendar-entry[data-near]) { background:#2b3933; background-image:none; border-color:#536458; color:#e2e9df; }
  .jy-status[data-theme="dark"] :is(.jy-readout,[data-campus-messages],.jy-calendar) { --jy-tab:#34463b; --jy-tab-ink:#d8e9d8; }
  .jy-status[data-theme="dark"] :is(.jy-location,.jy-kicker,.jy-date,.jy-scene-now b,.jy-card-school-cn,.jy-card-school-en,.jy-card-name-val,.jy-card-row,.jy-card-row b,.jy-card-row span,.jy-card-id-num,.jy-me-look,.jy-card-dossier summary,.jy-card-dossier-grid b,.jy-card-dossier-grid span,.jy-calendar-body,.jy-calendar-body .jy-page-note,[data-schedule],.jy-event-window,.jy-calendar-body .jy-forum-edition,.jy-feed strong,.jy-moment-title,.jy-feed p,.jy-moment-body,.jy-moment-comment,.jy-comment-text,.jy-detail span,.jy-detail b,.jy-inventory-name,.jy-inventory-description) { color:#d8e3d9; }
  .jy-status[data-theme="dark"] :is(.jy-moment-user,.jy-comment-user,.jy-moment-likes) { color:#a9c9e3; }
  .jy-status[data-theme="dark"] :is(.jy-month-stamp,.jy-event-state,.jy-mood,.jy-thought,.jy-card-badge,.jy-me-tag) { background:#394a3e; color:#e5d7b8; }
  .jy-status[data-theme="dark"] :is(button,input,select,textarea,.jy-avatar-button,.jy-album-action,.jy-map-button,.jy-inventory-button) { background:#35463e; border-color:#667c6e; color:#edf3eb; }
  .jy-status[data-theme="dark"] :is(button,input,select,textarea,summary):focus-visible { outline-color:#eed083; }
  .jy-status[data-theme="dark"] .jy-bar { background:#58675c; }
</style>
