    bus: ["傍晚亮起灯的校门公交站", "https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/bus.webp"]
  };
  const ALBUMS = {
    "许念安": [["nianan/campus.webp", "课间还作业"], ["nianan/library.webp", "图书馆的雨天"], ["nianan/home-diary.webp", "午后居家"], ["nianan/rainy-bookshop.webp", "雨天书店"]],
    "苏晓樯": [
      ["su/campus.png", "校园走廊"], ["su/outdoor.png", "天台咖啡"],
      ["su/pic-1.png", "校园随拍 01"], ["su/pic-2.png", "校园随拍 02"],
      ["su/pic-3.png", "校园随拍 03"], ["su/pic-4.png", "校园随拍 04"]
    ],
    "温书语": [["wen/campus.png", "午后教室"], ["wen/outdoor.png", "旧书店"]],
    "沈幼楚": [["shen/campus.png", "安静课间"], ["shen/outdoor.png", "奶茶店"]],
    "慕佳芊": [
      ["mu/campus.png", "办公室"], ["mu/outdoor.png", "旧街散步"],
      ["mu/pic-1.png", "校外照片 01"], ["mu/pic-2.png", "校外照片 02"],
      ["mu/pic-3.png", "校外照片 03"], ["mu/pic-4.png", "校外照片 04"], ["mu/pic-5.png", "校外照片 05"]
    ],
    "陈芷汀": [
      ["chen/campus.png", "校园门口"], ["chen/outdoor.png", "城市午后"],
      ["chen/pic-1.png", "校外照片 01"], ["chen/pic-2.png", "校外照片 02"], ["chen/pic-3.png", "校外照片 03"],
      ["chen/pic-4.png", "校外照片 04"], ["chen/pic-5.png", "校外照片 05"], ["chen/pic-6.png", "校外照片 06"]
    ],
    "虞淑婉": [
      ["yu/campus.png", "校长室"], ["yu/outdoor.png", "书店傍晚"],
      ["yu/pic-2.png", "生活照片 02"], ["yu/pic-3.png", "生活照片 03"], ["yu/pic-4.png", "生活照片 04"], ["yu/pic-6.jpg", "生活照片 06"]
    ]
  };

  let avatarHost = window;
  try { if (window.top.document) avatarHost = window.top; } catch (_) {}
  const AVATAR_EVENT = "jy-avatar-changed";
  const THEME_KEY = "jy-status-theme";
  const THEME_EVENT = "jy-status-theme-changed";
  let localTheme = "light";
  function readTheme() {
    try { return avatarHost.localStorage.getItem(THEME_KEY) || localTheme; }
    catch (_) { return localTheme; }
  }
  function syncTheme() {
    const dark = readTheme() === "dark";
    document.querySelectorAll(".jy-status").forEach(root => {
      root.dataset.theme = dark ? "dark" : "light";
      const button = root.querySelector('[data-action="toggle-theme"]');
      if (button) {
        button.setAttribute("aria-pressed", String(dark));
        const label = dark ? "日间" : "夜间";
        if (button.textContent !== label) button.textContent = label;
      }
    });
  }
  avatarHost.addEventListener(THEME_EVENT, syncTheme);
  window.addEventListener("storage", syncTheme);
  window.addEventListener("pagehide", () => {
    avatarHost.removeEventListener(THEME_EVENT, syncTheme);
    window.removeEventListener("storage", syncTheme);
  }, { once: true });

  function getStoredAvatar(name) {
    try { return avatarHost.localStorage.getItem(STORAGE_PREFIX + name); }
    catch (_) { return null; }
  }

  function syncAvatars() {
    document.querySelectorAll(".jy-avatar").forEach((avatar) => {
      const key = avatar.dataset.avatarKey || avatar.getAttribute("alt");
      const src = getStoredAvatar(key) || avatar.dataset.defaultSrc;
      if (src && avatar.getAttribute("src") !== src) {
        delete avatar.dataset.jyFallbackDone;
        avatar.src = src;
      }
    });
  }

  function announceAvatarChange() {
    avatarHost.dispatchEvent(new avatarHost.CustomEvent(AVATAR_EVENT));
  }

  function setStoredAvatar(name, dataUrl) {
    try {
      avatarHost.localStorage.setItem(STORAGE_PREFIX + name, dataUrl);
      announceAvatarChange();
      return true;
    } catch (_) { return false; }
  }

  function removeStoredAvatar(name) {
    try {
      avatarHost.localStorage.removeItem(STORAGE_PREFIX + name);
      announceAvatarChange();
      return true;
    } catch (_) { return false; }
  }

  function avatarStorageChanged(event) {
    if (event.key === null || event.key?.startsWith(STORAGE_PREFIX)) syncAvatars();
  }
  avatarHost.addEventListener(AVATAR_EVENT, syncAvatars);
  window.addEventListener("storage", avatarStorageChanged);
  window.addEventListener("pagehide", () => {
    avatarHost.removeEventListener(AVATAR_EVENT, syncAvatars);
    window.removeEventListener("storage", avatarStorageChanged);
  }, { once: true });

  function getStoredAlbum(name) {
    try {
      const parsed = JSON.parse(localStorage.getItem(ALBUM_STORAGE_PREFIX + name) || "[]");
      return Array.isArray(parsed) ? parsed.filter((item) => item && typeof item.src === "string") : [];
    } catch (error) {
      return [];
    }
  }

  function setStoredAlbum(name, items) {
    try {
      localStorage.setItem(ALBUM_STORAGE_PREFIX + name, JSON.stringify(items.slice(-6)));
      return true;
    } catch (error) {
      console.warn("相册保存失败，可能是浏览器本地存储空间不足。");
      return false;
    }
  }

  function escapeXmlText(value) {
    const amp = String.fromCharCode(38, 97, 109, 112, 59);
    const lt = String.fromCharCode(38, 108, 116, 59);
    const gt = String.fromCharCode(38, 103, 116, 59);
    const apos = String.fromCharCode(38, 35, 51, 57, 59);
    const quot = String.fromCharCode(38, 113, 117, 111, 116, 59);
    const table = { "&": amp, "<": lt, ">": gt, "'": apos, '"': quot };
    return String(value || "").replace(/[&<>'"]/g, (ch) => table[ch]);
  }

  function fallbackAvatarUri(label) {
    const text = escapeXmlText(String(label || "?").trim().slice(0, 1) || "?");
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 128 128"><rect width="128" height="128" rx="64" fill="#e6eee9"/><text x="64" y="82" text-anchor="middle" font-family="-apple-system,BlinkMacSystemFont,'PingFang SC','Microsoft YaHei',sans-serif" font-size="54" font-weight="600" fill="#3d6b5f">${text}</text></svg>`;
    return "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg);
  }

  function guardImage(image) {
    if (!image || image.dataset.jyGuard === "1" || image.classList.contains("jy-map-scene-image")) return;
    image.dataset.jyGuard = "1";
    image.addEventListener("error", () => {
      const fallback = image.dataset.fallbackSrc || "";
      if (fallback && image.getAttribute("src") !== fallback) {
        image.setAttribute("src", fallback);
        return;
      }
      if (image.dataset.jyFallbackDone === "1") return;
      image.dataset.jyFallbackDone = "1";
      if (image.classList.contains("jy-map-image")) {
        image.style.display = "none";
        const card = image.closest(".jy-map-card");
        if (card) card.dataset.imgMissing = "true";
        return;
      }
      if (image.classList.contains("jy-photo-viewer-image")) return;
      const label = image.getAttribute("alt") || image.dataset.avatarKey || image.dataset.albumKey || "?";
      image.src = fallbackAvatarUri(label);
    });
  }

  function compactImage(dataUrl, done, maxSize = 1536, quality = 0.95) {
    const image = new Image();
    image.onload = () => {
      const scale = Math.min(1, maxSize / Math.max(image.width, image.height));
      const canvas = document.createElement("canvas");
      canvas.width = Math.max(1, Math.round(image.width * scale));
      canvas.height = Math.max(1, Math.round(image.height * scale));
      const context = canvas.getContext("2d");
      context.drawImage(image, 0, 0, canvas.width, canvas.height);
      done(canvas.toDataURL("image/jpeg", quality));
    };
    image.onerror = () => done(dataUrl);
    image.src = dataUrl;
  }

  function revealModal(modal) {
    if (!modal) return;
    const card = modal.firstElementChild || modal;
    const reveal = () => {
      if (modal.dataset.open !== "true") return;
      try {
        card.scrollIntoView({ behavior: "smooth", block: "center", inline: "nearest" });
      } catch (error) {
        card.scrollIntoView();
      }
    };
    requestAnimationFrame(reveal);
    window.setTimeout(reveal, 90);
  }

  function sceneValue(element) {
    const value = element?.textContent.trim() || "";
    const bracePair = String.fromCharCode(123, 123);
    return (value.startsWith(bracePair) || /^(?:undefined$|null$|待确定$)/i.test(value)) ? "" : value;
  }

  function enhancePersonCards(root) {
    root.querySelectorAll(".jy-person").forEach((card) => {
      card.classList.add("jy-person-rich");
      card.querySelectorAll(".jy-detail-grid .jy-detail").forEach((row) => {
        if (row.querySelector("span")?.textContent.trim()) row.hidden = false;
      });
    });
