      post && typeof post.标识 === 'string' && post.标识 && typeof post.标题 === 'string' && typeof post.摘要 === 'string'
    ) : [];
    const isNotice = post => post.渠道 === '公告' || (post.渠道 === '班群' &&
      /老师|班主任|班长|班委|吴臻臻|慕佳芊|教务|教导处|年级组|体育组|校方|学生会|团委|学校|组织者|负责人/.test(post.来源 || ''));
