    const location = sceneValue(root.querySelector(".jy-location")).toLowerCase();
    mapModal.querySelector("[data-map-location]").textContent = "当前位置：" + (sceneValue(root.querySelector(".jy-location")) || "待确定");
    const places = [...mapModal.querySelectorAll(".jy-place")];
    const namesFor = (place) => [place.dataset.place, ...place.dataset.aliases.split("|")].map((alias) => alias.toLowerCase());
    let current = null;
    let matchLength = 0;
    places.forEach((place) => {
      namesFor(place).forEach((alias) => {
        if (alias.length > matchLength && (location === alias || (location.includes(alias) && alias.length >= 3 && !["公交站", "高铁站", "复印店", "文印店", "教师办公室"].includes(alias)))) {
          current = place;
          matchLength = alias.length;
        }
      });
      place.addEventListener("toggle", () => {
        const scene = MAP_SCENES[place.dataset.scene];
        const image = place.querySelector(".jy-map-scene-image");
        if (place.open && scene && image && !image.hasAttribute("src")) {
          const [alt, src] = scene;
          image.alt = alt;
          const fallback = src.replace('https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@', 'https://raw.githubusercontent.com/YangChen-cn/jiyang-school-assets/');
          image.addEventListener('error', () => {
            if (image.src !== fallback) image.src = fallback;
            else image.hidden = true;
          });
          image.src = src;
        }
      });
    });
    if (current) current.querySelector(".jy-place-current").hidden = false;
    const search = mapModal.querySelector("input[type=search]");
    search.addEventListener("input", () => {
      const query = search.value.trim().toLowerCase();
      places.forEach((place) => { place.hidden = !namesFor(place).some((alias) => alias.includes(query)); });
      mapModal.querySelectorAll(".jy-place-group").forEach((group) => { group.hidden = !group.querySelector(".jy-place:not([hidden])"); });
      mapModal.querySelector("[data-place-empty]").hidden = places.some((place) => !place.hidden);
    });
  }

  function bindStatus(root) {
    if (!root) return;
    syncTheme();
    if (root.dataset.avatarBoundVersion === "11") {
      applyStoredAvatars(root);
      root.querySelectorAll("img").forEach(guardImage);
      return;
    }
    root.dataset.avatarBound = "true";
    root.dataset.avatarBoundVersion = "11";

    const modal = root.querySelector(".jy-avatar-modal");
    const big = root.querySelector(".jy-avatar-big");
    const title = root.querySelector(".jy-avatar-title");
    const input = root.querySelector(".jy-avatar-input");
    const mapModal = root.querySelector(".jy-map-modal");
    const mapButton = root.querySelector('[data-action="open-map"]');
    const inventoryModal = root.querySelector(".jy-inventory-modal");
    const inventorySource = root.querySelector("[data-inventory-source]");
    const inventoryList = root.querySelector("[data-inventory-list]");
    const inventoryTitle = root.querySelector("[data-inventory-title]");
    const inventoryCount = root.querySelector("[data-inventory-count]");
    const albumModal = root.querySelector(".jy-album-modal");
    const albumGrid = root.querySelector("[data-album-grid]");
    const albumTitle = root.querySelector("[data-album-title]");
    const albumInput = root.querySelector("[data-album-input]");
    const photoViewer = root.querySelector(".jy-photo-viewer");
    const photoViewerImage = root.querySelector(".jy-photo-viewer-image");
    const photoViewerCaption = root.querySelector(".jy-photo-viewer-caption");
    const hasAvatarModal = Boolean(modal && big && title && input);
    let activeAvatar = null;
    let avatarImportId = 0;
    const avatarNotice = root.querySelector(".jy-avatar-notice");
    function showAvatarNotice(message) { if (avatarNotice) avatarNotice.textContent = message; }
    let activeAlbumKey = "";

    function getAvatars() {
      return Array.from(root.querySelectorAll(".jy-avatar"));
    }

    function applyStoredAvatars(scope) {
      getAvatars().forEach((avatar) => {
        const name = avatar.dataset.avatarName || avatar.getAttribute("alt") || "头像";
        const key = avatar.dataset.avatarKey || name;
        const saved = getStoredAvatar(key);
        if (!avatar.dataset.defaultSrc) avatar.dataset.defaultSrc = avatar.getAttribute("src") || fallbackAvatarUri(key === "主角" ? "我" : name);
        avatar.dataset.avatarName = name;
        avatar.dataset.avatarKey = key;
        avatar.setAttribute("role", "button");
        avatar.setAttribute("tabindex", "0");
        avatar.setAttribute("title", name + "头像");
        guardImage(avatar);
        if (saved && avatar.getAttribute("src") !== saved) avatar.src = saved;
        else if (!avatar.getAttribute("src")) avatar.src = avatar.dataset.defaultSrc;
      });
    }

    applyStoredAvatars(root);
    root.querySelectorAll("img").forEach(guardImage);

    function parseInventory(raw) {
      if (!raw || raw === "[]" || raw === "{}") return [];
      try {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) return parsed;
      } catch (error) {}

      const items = [];
      let current = null;
      raw.split(/\r?\n/).forEach((line) => {
        const name = line.match(/^\s*-?\s*名称\s*:\s*(.+)\s*$/);
        const description = line.match(/^\s*描述\s*:\s*(.+)\s*$/);
        if (name) {
          current = { 名称: name[1].trim().replace(/^['"]|['"]$/g, ""), 描述: "" };
          items.push(current);
        } else if (description && current) {
          current.描述 = description[1].trim().replace(/^['"]|['"]$/g, "");
        }
      });
      return items;
    }

    function renderInventory() {
      if (!inventoryList) return;
      const items = parseInventory(String(inventorySource?.textContent || "").trim())
        .filter((item) => item && item.名称);
      inventoryList.replaceChildren();
      if (inventoryCount) inventoryCount.textContent = String(items.length);
      if (inventoryTitle) inventoryTitle.textContent = items.length ? `重要物品栏 · ${items.length}` : "重要物品栏";

      if (!items.length) {
        const empty = document.createElement("div");
        empty.className = "jy-inventory-empty";
        empty.textContent = "暂无会影响后续剧情的重要物品。";
        inventoryList.append(empty);
        return;
      }

      items.forEach((item, index) => {
        const row = document.createElement("div");
        row.className = "jy-inventory-item";
        const mark = document.createElement("div");
        mark.className = "jy-inventory-mark";
        mark.textContent = String(index + 1).padStart(2, "0");
        const copy = document.createElement("div");
        const name = document.createElement("div");
        name.className = "jy-inventory-name";
        name.textContent = String(item.名称);
        const description = document.createElement("div");
        description.className = "jy-inventory-description";
        description.textContent = String(item.描述 || "暂无说明");
        copy.append(name, description);
        row.append(mark, copy);
        inventoryList.append(row);
      });
    }

    renderInventory();

    function openAvatar(avatar) {
      if (!hasAvatarModal) return;
      avatarImportId++;
      activeAvatar = avatar;
      showAvatarNotice("图片仅保存在此浏览器，刷新后自动读取。");
      const name = avatar.dataset.avatarName || avatar.getAttribute("alt") || "头像";
      big.src = avatar.src;
      big.alt = name;
      title.textContent = name;
      modal.dataset.open = "true";
      modal.setAttribute("aria-hidden", "false");
      revealModal(modal);
    }

    function closeAvatar() {
      if (!hasAvatarModal) return;
      modal.dataset.open = "false";
      modal.setAttribute("aria-hidden", "true");
      input.value = "";
      avatarImportId++;
      activeAvatar?.focus({ preventScroll: true });
    }

    try {
      bindSceneReadouts(root, mapModal);
    } catch (error) {
      console.warn("[暨阳状态栏] 场景绑定失败", error);
    }
    root.querySelectorAll(".jy-mood, .jy-thought, .jy-me-look").forEach((field) => {
      if (!sceneValue(field)) field.hidden = true;
    });

    let mapReturnScroll = null;
    mapModal?.addEventListener('keydown', event => {
      if (event.key !== 'Tab') return;
      const focusable = [...mapModal.querySelectorAll('button,input,summary,select')].filter(el => !el.closest('[hidden]') && el.getClientRects().length);
      const first = focusable[0], last = focusable[focusable.length - 1];
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
    });
    function openMap() {
      mapReturnScroll = { x: window.scrollX, y: window.scrollY };
      if (!mapModal) return;
      mapModal.dataset.open = "true";
      mapModal.setAttribute("aria-hidden", "false");
      mapModal.querySelector('[data-action="close-map"]')?.focus({ preventScroll: true });
      revealModal(mapModal);
    }

    function closeMap() {
      if (!mapModal) return;
      mapButton?.focus({ preventScroll: true });
      mapModal.dataset.open = "false";
      mapModal.setAttribute("aria-hidden", "true");
      if (mapReturnScroll) window.scrollTo(mapReturnScroll.x, mapReturnScroll.y);
    }

    function openInventory() {
      if (!inventoryModal) return;
      renderInventory();
      inventoryModal.dataset.open = "true";
      inventoryModal.setAttribute("aria-hidden", "false");
      revealModal(inventoryModal);
    }

    function closeInventory() {
      if (!inventoryModal) return;
      inventoryModal.dataset.open = "false";
      inventoryModal.setAttribute("aria-hidden", "true");
    }

    function setAvatarFromAlbum(name, src) {
      const avatar = getAvatars().find((item) => (item.dataset.avatarKey || item.getAttribute("alt")) === name);
      if (!avatar || !src) return;
      if (!setStoredAvatar(name, src)) {
        openAvatar(avatar);
        showAvatarNotice("头像未保存：浏览器缓存不可用或空间不足。请换一张较小的图片。");
      }
    }

    function makeAlbumItem(item, isLocal) {
      const card = document.createElement("article");
      card.className = "jy-album-item";
      const image = document.createElement("img");
      image.className = "jy-album-photo";
      image.src = item.src;
      image.alt = item.label;
      image.loading = "lazy";
      image.dataset.fallbackSrc = item.fallbackSrc || "";
      image.setAttribute("role", "button");
      image.setAttribute("tabindex", "0");
      image.dataset.action = "open-album-photo";
      image.dataset.photoSrc = item.src;
      image.dataset.photoLabel = item.label;
      guardImage(image);
      const caption = document.createElement("div");
      caption.className = "jy-album-caption";
      caption.textContent = item.label;
      const actions = document.createElement("div");
      actions.className = "jy-album-actions";
      const use = document.createElement("button");
      use.className = "jy-album-action";
      use.type = "button";
      use.textContent = "设为头像";
      use.dataset.action = "set-album-avatar";
      use.dataset.albumSrc = item.src;
      actions.append(use);
      if (isLocal) {
        const remove = document.createElement("button");
        remove.className = "jy-album-action";
        remove.type = "button";
        remove.textContent = "删除";
        remove.dataset.kind = "remove";
        remove.dataset.action = "remove-album-photo";
        remove.dataset.albumId = item.id;
        actions.append(remove);
      }
      card.append(image, caption, actions);
      return card;
    }

    function renderAlbum() {
      if (!albumGrid || !activeAlbumKey) return;
      const remote = (ALBUMS[activeAlbumKey] || []).map(([path, label]) => ({ src: `${ASSET_BASE}/${path}`, fallbackSrc: `${ASSET_BASE_FALLBACK}/${path}`, label }));
      const local = getStoredAlbum(activeAlbumKey);
      albumGrid.replaceChildren();
      if (!remote.length && !local.length) {
        const empty = document.createElement("div");
        empty.className = "jy-album-empty";
        empty.textContent = "这本相册暂时没有照片。";
        albumGrid.append(empty);
        return;
      }
      remote.forEach((item) => albumGrid.append(makeAlbumItem(item, false)));
      local.forEach((item) => albumGrid.append(makeAlbumItem(item, true)));
    }

    function openAlbum(name) {
      if (!albumModal || !name) return;
      activeAlbumKey = name;
      if (albumTitle) albumTitle.textContent = `${name}的相册`;
      renderAlbum();
      albumModal.dataset.open = "true";
      albumModal.setAttribute("aria-hidden", "false");
      revealModal(albumModal);
    }

    function closeAlbum() {
      if (!albumModal) return;
      albumModal.dataset.open = "false";
      albumModal.setAttribute("aria-hidden", "true");
      if (albumInput) albumInput.value = "";
    }

    function openPhotoViewer(src, label) {
      if (!photoViewer || !photoViewerImage || !src) return;
      photoViewerImage.src = src;
      photoViewerImage.alt = label || "相册照片";
      if (photoViewerCaption) photoViewerCaption.textContent = label || "相册照片";
      photoViewer.dataset.open = "true";
      photoViewer.setAttribute("aria-hidden", "false");
      revealModal(photoViewer);
    }

    function closePhotoViewer() {
      if (!photoViewer) return;
      photoViewer.dataset.open = "false";
      photoViewer.setAttribute("aria-hidden", "true");
    }

    root.addEventListener("click", (event) => {
      if (event.target.closest('[data-action="toggle-theme"]')) {
        localTheme = root.dataset.theme === "dark" ? "light" : "dark";
        try { avatarHost.localStorage.setItem(THEME_KEY, localTheme); } catch (_) {}
        syncTheme();
        try { avatarHost.dispatchEvent(new avatarHost.CustomEvent(THEME_EVENT)); } catch (_) {}
        return;
      }
      if (event.target.closest('[data-action="open-map"]')) {
        openMap();
        return;
      }

      if (event.target.closest('[data-action="open-inventory"]')) {
        openInventory();
        return;
      }

      const albumButton = event.target.closest('[data-action="open-album"]');
      if (albumButton && root.contains(albumButton)) {
        openAlbum(albumButton.dataset.albumKey || "");
        return;
      }

      const albumPhoto = event.target.closest('[data-action="open-album-photo"]');
      if (albumPhoto && activeAlbumKey) {
        openPhotoViewer(albumPhoto.dataset.photoSrc || "", albumPhoto.dataset.photoLabel || "");
        return;
      }

      const setAlbumAvatar = event.target.closest('[data-action="set-album-avatar"]');
      if (setAlbumAvatar && activeAlbumKey) {
        setAvatarFromAlbum(activeAlbumKey, setAlbumAvatar.dataset.albumSrc || "");
        return;
      }

      const removeAlbumPhoto = event.target.closest('[data-action="remove-album-photo"]');
      if (removeAlbumPhoto && activeAlbumKey) {
        const remaining = getStoredAlbum(activeAlbumKey).filter((item) => item.id !== removeAlbumPhoto.dataset.albumId);
        setStoredAlbum(activeAlbumKey, remaining);
        renderAlbum();
        return;
      }

      if (hasAvatarModal && (event.target === modal || event.target.closest('[data-action="close-avatar"]'))) {
        closeAvatar();
        return;
      }

      if (hasAvatarModal && event.target.closest('[data-action="reset-avatar"]') && activeAvatar) {
        const key = activeAvatar.dataset.avatarKey || activeAvatar.dataset.avatarName || activeAvatar.getAttribute("alt") || "头像";
        avatarImportId++;
        if (removeStoredAvatar(key)) {
          big.src = activeAvatar.src;
          showAvatarNotice("已还原默认头像并清除自选缓存。");
        } else showAvatarNotice("还原失败：浏览器缓存不可用。");
        return;
      }

      const avatar = event.target.closest(".jy-avatar");
      if (avatar && root.contains(avatar)) {
        openAvatar(avatar);
        return;
      }

      if (event.target === mapModal || event.target.closest('[data-action="close-map"]')) {
        closeMap();
        return;
      }

      if (event.target === inventoryModal || event.target.closest('[data-action="close-inventory"]')) {
        closeInventory();
        return;
      }

      if (event.target === albumModal || event.target.closest('[data-action="close-album"]')) {
        closeAlbum();
        return;
      }

      if (event.target === photoViewer || event.target.closest('[data-action="close-photo-viewer"]')) {
        closePhotoViewer();
        return;
      }
    });

    root.addEventListener("keydown", (event) => {
      if ((event.key === "Enter" || event.key === " ") && event.target.classList.contains("jy-avatar")) {
        event.preventDefault();
        openAvatar(event.target);
      }
      if ((event.key === "Enter" || event.key === " ") && event.target.matches('[data-action="open-album-photo"]')) {
        event.preventDefault();
        openPhotoViewer(event.target.dataset.photoSrc || "", event.target.dataset.photoLabel || "");
      }
      if (event.key === "Escape" && hasAvatarModal && modal.dataset.open === "true") closeAvatar();
      if (event.key === "Escape" && mapModal && mapModal.dataset.open === "true") closeMap();
      if (event.key === "Escape" && inventoryModal && inventoryModal.dataset.open === "true") closeInventory();
      if (event.key === "Escape" && albumModal && albumModal.dataset.open === "true") closeAlbum();
      if (event.key === "Escape" && photoViewer && photoViewer.dataset.open === "true") closePhotoViewer();
    });

    if (hasAvatarModal) {
      input.addEventListener("change", () => {
        const file = input.files && input.files[0];
        input.value = "";
        if (!file || !activeAvatar) return;
        if (!/^image\/(png|jpeg|webp|gif)$/.test(file.type) || file.size > 10 * 1024 * 1024) {
          showAvatarNotice("请选择不超过 10 MB 的 PNG、JPEG、WebP 或 GIF 图片。");
          return;
        }
        const target = activeAvatar;
        const key = target.dataset.avatarKey;
        const requestId = ++avatarImportId;
        showAvatarNotice("正在读取图片…");
        const reader = new FileReader();
        const fail = () => {
          if (requestId === avatarImportId) showAvatarNotice("图片读取失败，原头像已保留，请换一张图片。");
        };
        reader.onerror = fail;
        reader.onload = () => {
          const image = new Image();
          image.onerror = fail;
          image.onload = () => {
            if (requestId !== avatarImportId) return;
            try {
              const scale = Math.min(1, 512 / Math.max(image.width, image.height));
              const canvas = document.createElement("canvas");
              canvas.width = Math.max(1, Math.round(image.width * scale));
              canvas.height = Math.max(1, Math.round(image.height * scale));
              canvas.getContext("2d").drawImage(image, 0, 0, canvas.width, canvas.height);
              const compactUrl = canvas.toDataURL("image/png");
              if (!setStoredAvatar(key, compactUrl)) {
                showAvatarNotice("头像未保存：浏览器缓存不可用或空间不足，原头像已保留。");
                return;
              }
              big.src = compactUrl;
              showAvatarNotice("已保存到本机缓存，状态栏和正文头像已同步。");
            } catch (_) { fail(); }
          };
          image.src = String(reader.result || "");
        };
        reader.readAsDataURL(file);
      });
    }

    if (albumInput) {
      albumInput.addEventListener("change", () => {
        const file = albumInput.files && albumInput.files[0];
        if (!file || !activeAlbumKey || !file.type.startsWith("image/")) return;
        const reader = new FileReader();
        reader.onload = () => {
          compactImage(String(reader.result || ""), (compactUrl) => {
            const items = getStoredAlbum(activeAlbumKey);
            items.push({
              id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
              src: compactUrl,
              label: "自定义照片"
            });
            if (setStoredAlbum(activeAlbumKey, items)) renderAlbum();
            albumInput.value = "";
          }, 960, 0.88);
        };
        reader.readAsDataURL(file);
      });
    }
  }

  let initTimer = null;

  function init() {
    document.querySelectorAll(".jy-status").forEach(bindStatus);
  }

  function scheduleInit() {
    if (initTimer) return;
    initTimer = setTimeout(() => {
      initTimer = null;
      init();
    }, 150);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }

  setTimeout(init, 100);
  setTimeout(init, 500);
  setTimeout(init, 1200);

  if (typeof MutationObserver !== "undefined") {
    const observer = new MutationObserver(scheduleInit);
    observer.observe(document.documentElement, { childList: true, subtree: true });
  }
})();
</script>
