    player.querySelector('[data-role="volume-value"]').textContent = `${state.volume}%`;
    try { api('setAudioSettings')?.('bgm', { volume: state.volume }); } catch (error) {
      if (!quiet) notify('音量设置失败，请确认酒馆助手音频功能可用。', 'error');
    }
  }

  function renderPlaylist() {
    const list = player.querySelector('[data-role="playlist"]');
    const count = player.querySelector('[data-role="count"]');
    list.replaceChildren();
    count.textContent = String(state.playlist.length);

    if (!state.playlist.length) {
      const empty = doc.createElement('div');
      empty.className = 'jy-music-empty';
      empty.textContent = '歌单还是空的。添加一条可直接播放的音频链接。';
      list.append(empty);
      return;
    }

    state.playlist.forEach((track, index) => {
      const row = doc.createElement('div');
      row.className = 'jy-music-track';
      if (index === state.currentIndex) row.dataset.current = 'true';
      const select = doc.createElement('button');
      select.type = 'button';
      select.className = 'jy-music-track-select';
      select.dataset.index = String(index);
      select.title = trackSources(track)[0] || '';
      if (track.__unavailable) row.dataset.unavailable = 'true';
      const art = doc.createElement('span');
      art.className = 'jy-music-track-art';
      if (track.cover) art.style.backgroundImage = `url(${JSON.stringify(track.cover)})`;
      const trackTitle = doc.createElement('span');
      trackTitle.textContent = track.title + (track.__unavailable ? '（不可用）' : '');
      select.append(art, trackTitle);
      const remove = doc.createElement('button');
      remove.type = 'button';
      remove.className = 'jy-music-track-remove';
      remove.dataset.removeIndex = String(index);
      remove.setAttribute('aria-label', `删除 ${track.title}`);
      remove.title = '删除曲目';
      remove.textContent = '×';
      row.append(select, remove);
      list.append(row);
    });
  }

  function refreshPlayback() {
    const title = player?.querySelector('[data-role="now-title"]');
    const status = player?.querySelector('[data-role="status"]');
    const toggle = player?.querySelector('[data-action="toggle"]');
    if (!title || !status || !toggle) return;
    const fallback = currentTrack();
    try {
      const current = api('getCurrentAudio')?.('bgm');
      const playing = Boolean(current?.playing);
      const progress = Math.max(0, Math.min(100, Number(current?.progress) || 0));
      if (playing && current?.title && fallback && current.title !== fallback.title) {
        const syncedIndex = state.playlist.findIndex(track => track.title === current.title);
        if (syncedIndex >= 0 && syncedIndex !== state.currentIndex) {
          state.currentIndex = syncedIndex;
          saveState();
          renderPlaylist();
        }
      }
      title.textContent = current?.title || fallback?.title || '尚未选择歌曲';
      status.textContent = playing ? `正在播放 ${Math.round(progress)}%` : (fallback ? '已暂停' : '等待播放');
      toggle.textContent = playing ? '❚❚' : '▶';
      toggle.title = playing ? '暂停' : '播放';
      player.dataset.playing = playing ? 'true' : 'false';
      player.style.setProperty('--jy-progress', `${progress}%`);
      const progressControl = player.querySelector('[data-role="progress"]');
      progressControl?.setAttribute('aria-valuenow', String(Math.round(progress)));
      // 曲终行为交给酒馆助手自身的 audio mode（playMode 已同步到 repeat_all/repeat_one/shuffle），
      // 不再用 99.8% 轮询抢切歌，避免 TH 把 progress 归零导致漏判/双切。

    } catch (_) {
      title.textContent = fallback?.title || '尚未选择歌曲';
      status.textContent = '等待酒馆助手音频接口';
    }
  }

  function play(index = state.currentIndex) {
    if (!state.playlist.length) {
      warn('请先添加歌曲直链。');
      return;
    }
    const nextIndex = index < 0 ? 0 : ((index % state.playlist.length) + state.playlist.length) % state.playlist.length;
    const track = state.playlist[nextIndex];
    const sources = trackSources(track);
    if (!sources.length) {
      warn('当前歌曲没有可用的音频直链。');
      return;
    }
    const playAudio = api('playAudio');
    if (!playAudio) {
      warn('未检测到酒馆助手音频接口。');
      return;
    }
    const sourceIndex = trackSourceIndex(track);
    const url = sources[sourceIndex];
    try {
      state.currentIndex = nextIndex;
      track.__unavailable = false;
      saveState();
      syncThAudioMode();
      api('setAudioSettings')?.('bgm', { enabled: true, muted: false, volume: state.volume });
      playAudio('bgm', { title: track.title, url });
      renderPlaylist();
      refreshPlayback();
      schedulePlaybackCheck(track, nextIndex, sourceIndex, url);
    } catch (error) {
      warn(`无法播放：${error.message || '请检查音频链接。'}`);
    }
  }

  function schedulePlaybackCheck(track, index, sourceIndex, url) {
    appWindow.setTimeout(() => {
      if (state.currentIndex !== index) return;
      const current = api('getCurrentAudio')?.('bgm');
      if (current && current.title && current.title !== track.title) return;
      const audio = matchingAudioElement(url) || matchingAudioElement(current?.src);
      const failed = !audio
        || audio.error != null
        || audio.networkState === 3
        || (audio.readyState === 0 && audio.paused);
      if (!failed) return;
      const nextSource = sourceIndex + 1;
      if (nextSource < trackSources(track).length) {
        track.__sourceIndex = nextSource;
        warn(`「${track.title}」主源加载失败，正在尝试备用源…`);
        play(index);
        return;
      }
      track.__sourceIndex = 0;
      track.__unavailable = true;
      saveState();
      renderPlaylist();
      warn(`「${track.title}」音频加载失败，已在歌单中标记不可用。`);
    }, 2000);
  }

  function pause() {
    try {
      const pauseAudio = api('pauseAudio');
      if (!pauseAudio) throw new Error('未检测到酒馆助手音频接口');
      pauseAudio('bgm');
      refreshPlayback();
    } catch (error) {
      notify(`无法暂停：${error.message || '音频接口不可用。'}`, 'error');
    }
  }

  function togglePlayback() {
    try {
      if (api('getCurrentAudio')?.('bgm')?.playing) pause();
      else play();
    } catch (_) {
      play();
    }
  }

  function addTrack() {
    const titleInput = player.querySelector('[data-role="title-input"]');
    const urlInput = player.querySelector('[data-role="url-input"]');
    const coverInput = player.querySelector('[data-role="cover-input"]');
    const title = titleInput.value.trim();
    const url = urlInput.value.trim();
    const cover = coverInput.value.trim();
    if (!title || !url) {
      notify('请填写歌曲标题和音频直链。', 'error');
      return;
    }
    try {
      const parsed = new URL(url);
      if (!['http:', 'https:'].includes(parsed.protocol)) throw new Error('仅支持 HTTP(S) 音频链接');
    } catch (error) {
      notify(error.message || '音频链接格式无效。', 'error');
      return;
    }
    if (cover) {
      try {
        const parsed = new URL(cover);
        if (!['http:', 'https:'].includes(parsed.protocol)) throw new Error('封面仅支持 HTTP(S) 图片链接');
      } catch (error) {
        notify(error.message || '封面链接格式无效。', 'error');
        return;
      }
    }
    if (state.playlist.some(track => track.title === title || trackSources(track).includes(url))) {
      notify('歌单中已有同名或相同链接的歌曲。', 'error');
      return;
    }
    state.playlist.push({ title, sources: [url], cover });
    saveState();
    titleInput.value = '';
    urlInput.value = '';
    coverInput.value = '';
    renderPlaylist();
    notify(`已加入「${title}」。`);
  }

  function removeTrack(index) {
    state.playlist.splice(index, 1);
    if (state.currentIndex === index) state.currentIndex = -1;
    else if (state.currentIndex > index) state.currentIndex -= 1;
    saveState();
    renderPlaylist();
    refreshPlayback();
  }

  function cycleMode() {
    const sequence = ['list', 'single', 'shuffle'];
    state.playMode = sequence[(sequence.indexOf(state.playMode) + 1) % sequence.length];
    saveState();
    syncThAudioMode();
    renderMode();
    notify(`已切换为${modeMeta().label}。`);
  }

  function renderMode() {
    const button = player?.querySelector('[data-action="mode"]');
    const label = player?.querySelector('[data-role="mode-label"]');
    if (!button || !label) return;
    const meta = modeMeta();
    button.textContent = meta.icon;
    button.title = `${meta.label}：${meta.hint}`;
    button.dataset.mode = state.playMode;
    label.textContent = meta.label;
  }

  function applyPosition() {
    if (!state.position) {
      player.style.right = '20px';
      player.style.bottom = '20px';
      player.style.left = 'auto';
      player.style.top = 'auto';
      return;
    }
    const maxLeft = Math.max(8, appWindow.innerWidth - player.offsetWidth - 8);
    const maxTop = Math.max(8, appWindow.innerHeight - player.offsetHeight - 8);
    state.position.left = Math.max(8, Math.min(maxLeft, state.position.left));
    state.position.top = Math.max(8, Math.min(maxTop, state.position.top));
    player.style.left = `${state.position.left}px`;
    player.style.top = `${state.position.top}px`;
    player.style.right = 'auto';
    player.style.bottom = 'auto';
  }

  function setCollapsed(collapsed) {
    state.collapsed = collapsed;
    player.dataset.collapsed = collapsed ? 'true' : 'false';
    const handle = player.querySelector('[data-role="drag-handle"]');
    handle.title = collapsed ? '点击展开，拖动移动' : '点击收起为小球，拖动移动';
    saveState();
    appWindow.setTimeout(applyPosition, 0);
  }

  function injectStyle() {
    if (doc.getElementById(STYLE_ID)) return;
    const style = doc.createElement('style');
    style.id = STYLE_ID;
    style.textContent = `
      #${ROOT_ID}{--jy-progress:0%;position:fixed;z-index:2147483000;width:min(342px,calc(100vw - 16px));border:1px solid #d7e3dc;border-radius:8px;background:#fffdf8;color:#29322f;box-shadow:0 18px 45px rgba(37,66,58,.24);font:12px/1.45 "Noto Sans SC","Microsoft YaHei",sans-serif;overflow:hidden;user-select:none;transition:width .18s ease,height .18s ease,border-radius .18s ease}
      #${ROOT_ID} *{box-sizing:border-box}#${ROOT_ID} .jy-music-head{display:flex;align-items:center;gap:8px;min-height:40px;padding:0 12px;background:#277d70;color:#fff;cursor:grab}#${ROOT_ID} .jy-music-head:active{cursor:grabbing}#${ROOT_ID} .jy-music-brand{min-width:0;flex:1;font-weight:800;letter-spacing:0}#${ROOT_ID} .jy-music-head-tip{color:rgba(255,255,255,.72);font-size:10px}#${ROOT_ID} .jy-music-ball{display:none}#${ROOT_ID}[data-collapsed="true"]{width:62px;height:62px;border-radius:50%;border-color:#fff;background:#d9ecff;box-shadow:0 10px 25px rgba(48,120,197,.36);overflow:visible}#${ROOT_ID}[data-collapsed="true"] .jy-music-head{display:grid;width:62px;height:62px;min-height:0;padding:0;place-items:center;border-radius:50%;background:transparent;cursor:grab}#${ROOT_ID}[data-collapsed="true"] .jy-music-brand,#${ROOT_ID}[data-collapsed="true"] .jy-music-head-tip{display:none}#${ROOT_ID}[data-collapsed="true"] .jy-music-ball{display:block;width:58px;height:58px;border:1px solid rgba(255,255,255,.82);border-radius:50%;background:#e7f4ff center/cover no-repeat;background-image:url("${COLLAPSED_ART}");box-shadow:inset 0 0 0 1px rgba(38,115,213,.18);color:transparent;font-size:0;transition:transform .16s ease}#${ROOT_ID}[data-collapsed="true"] .jy-music-head:hover .jy-music-ball{transform:scale(1.06)}
      #${ROOT_ID} .jy-music-body{padding:11px;background:linear-gradient(145deg,#fffdf8 0%,#f5faf6 64%,#fff6f2 100%)}#${ROOT_ID}[data-collapsed="true"] .jy-music-body{display:none}#${ROOT_ID} .jy-music-now{display:grid;grid-template-columns:53px minmax(0,1fr);gap:10px;align-items:center;padding:9px;border:1px solid #dce8df;background:#fff;box-shadow:0 5px 14px rgba(43,91,78,.07)}#${ROOT_ID} .jy-music-note{display:grid;width:53px;height:53px;place-items:center;border-radius:6px;background:#e8a374;color:#fff;font-size:23px;box-shadow:inset 0 -5px 0 rgba(126,61,40,.15)}#${ROOT_ID} .jy-music-now-title{overflow:hidden;font-size:13px;font-weight:800;text-overflow:ellipsis;white-space:nowrap}#${ROOT_ID} .jy-music-status{margin-top:3px;color:#6d7873;font-size:11px}#${ROOT_ID} .jy-music-progress{height:12px;margin-top:5px;padding:4px 0;cursor:pointer;touch-action:none}#${ROOT_ID} .jy-music-progress::before{display:block;height:4px;border-radius:999px;background:#e3ece5;content:""}#${ROOT_ID} .jy-music-progress::after{display:block;width:var(--jy-progress);height:4px;margin-top:-4px;border-radius:999px;background:#e68e6b;content:"";transition:width .25s linear}#${ROOT_ID} .jy-music-progress:focus-visible{outline:2px solid rgba(229,143,108,.48);outline-offset:2px}
      #${ROOT_ID} .jy-music-controls{display:grid;grid-template-columns:34px 1fr 1.25fr 1fr;gap:6px;margin-top:10px}#${ROOT_ID} .jy-music-controls button{min-height:33px;border:1px solid #d2e1d8;border-radius:5px;background:#fff;color:#277d70;cursor:pointer;font-weight:800}#${ROOT_ID} .jy-music-controls button:hover{background:#eff7f2}#${ROOT_ID} [data-action="toggle"]{background:#277d70!important;color:#fff!important;border-color:#277d70!important}#${ROOT_ID} [data-action="mode"][data-mode="single"],#${ROOT_ID} [data-action="mode"][data-mode="shuffle"]{color:#bd654a;border-color:#e4b4a0;background:#fff8f4}
      #${ROOT_ID} .jy-music-mode-note{margin-top:6px;color:#75837c;font-size:10px;text-align:center}#${ROOT_ID} .jy-music-volume{display:grid;grid-template-columns:auto minmax(0,1fr)34px;gap:7px;align-items:center;margin-top:10px;color:#6d7873}#${ROOT_ID} input[type="range"]{accent-color:#e58f6c}#${ROOT_ID} .jy-music-add{display:grid;grid-template-columns:94px minmax(0,1fr)30px;gap:6px;margin-top:11px}#${ROOT_ID} .jy-music-add-extra{display:grid;grid-template-columns:1fr;margin-top:6px}#${ROOT_ID} input{min-width:0;border:1px solid #d2e1d8;border-radius:4px;background:#fff;color:#29322f;font:inherit;padding:7px}#${ROOT_ID} input:focus{outline:2px solid rgba(229,143,108,.28);border-color:#e58f6c}#${ROOT_ID} .jy-music-add button{border:0;border-radius:4px;background:#cf7658;color:#fff;cursor:pointer;font-weight:800}
      #${ROOT_ID} .jy-music-list-head{display:flex;justify-content:space-between;margin:12px 0 6px;color:#6d7873;font-size:11px;font-weight:800}#${ROOT_ID} .jy-music-playlist{display:grid;max-height:158px;gap:4px;overflow:auto}#${ROOT_ID} .jy-music-empty{border:1px dashed #cbded2;color:#6d7873;padding:12px;text-align:center}#${ROOT_ID} .jy-music-track{display:grid;grid-template-columns:minmax(0,1fr)27px;border:1px solid #e1ebe4;background:#fff}#${ROOT_ID} .jy-music-track[data-current="true"]{border-left:3px solid #e58f6c;background:#fff8f4}#${ROOT_ID} .jy-music-track button{border:0;background:transparent;color:#29322f;cursor:pointer;font:inherit}#${ROOT_ID} .jy-music-track-select{display:flex;align-items:center;gap:7px;overflow:hidden;padding:6px;text-align:left;text-overflow:ellipsis;white-space:nowrap}#${ROOT_ID} .jy-music-track-art{display:block;width:24px;height:24px;flex:0 0 24px;border-radius:50%;background:#c6ddd1 center/cover no-repeat}#${ROOT_ID} .jy-music-track-remove{color:#bb674d;font-size:17px}#${ROOT_ID} .jy-music-notice{min-height:16px;margin-top:8px;color:#6d7873;font-size:11px}#${ROOT_ID} .jy-music-notice[data-type="error"]{color:#a3483b}
      #${ROOT_ID} .jy-music-track[data-unavailable="true"]{opacity:.5}
      @media(max-width:640px){#${ROOT_ID}{width:min(320px,calc(100vw - 12px))}}
    `;
    doc.head.append(style);
  }

  function injectPlayer() {
    doc.getElementById(ROOT_ID)?.remove();
    player = doc.createElement('section');
    player.id = ROOT_ID;
    player.dataset.collapsed = state.collapsed ? 'true' : 'false';
    player.innerHTML = `
      <div class="jy-music-head" data-role="drag-handle" title="${state.collapsed ? '点击展开，拖动移动' : '点击收起为小球，拖动移动'}"><span class="jy-music-brand">暨阳中学广播台</span><span class="jy-music-head-tip">点击收起</span><span class="jy-music-ball">暨阳</span></div>
      <div class="jy-music-body">
        <div class="jy-music-now"><span class="jy-music-note">♪</span><div><div class="jy-music-now-title" data-role="now-title">尚未选择歌曲</div><div class="jy-music-status" data-role="status">等待播放</div><div class="jy-music-progress" data-role="progress" role="slider" tabindex="0" aria-label="播放进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"></div></div></div>
        <div class="jy-music-controls"><button type="button" data-action="mode" title="列表循环">↻</button><button type="button" data-action="previous" title="上一首">◀</button><button type="button" data-action="toggle" title="播放">▶</button><button type="button" data-action="next" title="下一首">▶</button></div>
        <div class="jy-music-mode-note" data-role="mode-label">列表循环</div>
        <label class="jy-music-volume"><span>音量</span><input type="range" min="0" max="100" value="${state.volume}" data-role="volume"><span data-role="volume-value">${state.volume}%</span></label>
        <div class="jy-music-add"><input data-role="title-input" placeholder="歌曲标题"><input data-role="url-input" placeholder="https:// 音频直链"><button type="button" data-action="add" title="加入歌单">+</button></div>
        <div class="jy-music-add-extra"><input data-role="cover-input" placeholder="封面图片链接（可选）"></div>
        <div class="jy-music-list-head"><span>本卡歌单</span><span data-role="count">0</span></div><div class="jy-music-playlist" data-role="playlist"></div>
        <div class="jy-music-notice" data-role="notice" aria-live="polite"></div>
      </div>`;
    doc.body.append(player);
    applyPosition();
    renderPlaylist();
    setVolume(state.volume, true);
    renderMode();
    refreshPlayback();

    player.addEventListener('click', event => {
      const target = event.target.closest('[data-action], [data-index], [data-remove-index]');
      if (!target) return;
      if (target.dataset.action === 'toggle') togglePlayback();
      if (target.dataset.action === 'mode') cycleMode();
      if (target.dataset.action === 'previous') play((state.currentIndex < 0 ? 0 : state.currentIndex - 1));
      if (target.dataset.action === 'next') play(nextIndex(state.currentIndex, false));
      if (target.dataset.action === 'add') addTrack();
      if (target.dataset.index !== undefined) play(Number(target.dataset.index));
      if (target.dataset.removeIndex !== undefined) removeTrack(Number(target.dataset.removeIndex));
    });
    player.querySelector('[data-role="volume"]').addEventListener('input', event => setVolume(event.target.value));

    const progress = player.querySelector('[data-role="progress"]');
    progress.addEventListener('pointerdown', event => {
      progressDrag = true;
      progress.setPointerCapture?.(event.pointerId);
      seekFromPointer(event);
      event.preventDefault();
    });
    progress.addEventListener('pointermove', event => {
      if (progressDrag) seekFromPointer(event);
    });
    progress.addEventListener('pointerup', event => {
      if (progressDrag) seekFromPointer(event);
      progressDrag = false;
    });
    progress.addEventListener('pointercancel', () => { progressDrag = false; });
    progress.addEventListener('keydown', event => {
      const current = Number(player.style.getPropertyValue('--jy-progress').replace('%', '')) || 0;
      if (event.key === 'ArrowLeft' || event.key === 'ArrowDown') { seekTo((current - 5) / 100); event.preventDefault(); }
      if (event.key === 'ArrowRight' || event.key === 'ArrowUp') { seekTo((current + 5) / 100); event.preventDefault(); }
      if (event.key === 'Home') { seekTo(0); event.preventDefault(); }
      if (event.key === 'End') { seekTo(1); event.preventDefault(); }
    });

    const handle = player.querySelector('[data-role="drag-handle"]');
    handle.addEventListener('pointerdown', event => {
      const rect = player.getBoundingClientRect();
      drag = { pointerId: event.pointerId, offsetX: event.clientX - rect.left, offsetY: event.clientY - rect.top, startX: event.clientX, startY: event.clientY, moved: false };
      handle.setPointerCapture?.(event.pointerId);
    });
    handle.addEventListener('pointermove', event => {
      if (!drag || drag.pointerId !== event.pointerId) return;
      if (Math.abs(event.clientX - drag.startX) > 4 || Math.abs(event.clientY - drag.startY) > 4) drag.moved = true;
      state.position = { left: event.clientX - drag.offsetX, top: event.clientY - drag.offsetY };
      applyPosition();
    });
    handle.addEventListener('pointerup', event => {
      if (!drag || drag.pointerId !== event.pointerId) return;
      const moved = drag.moved;
      drag = null;
      saveState();
      if (!moved) setCollapsed(!state.collapsed);
    });
    handle.addEventListener('pointercancel', () => { drag = null; });
  }

  injectStyle();
  injectPlayer();
  syncThAudioMode();
  timer = appWindow.setInterval(refreshPlayback, 900);
  appWindow.addEventListener('resize', applyPosition);
  function destroyMusicPlayer() {
    appWindow.clearInterval(timer);
    appWindow.removeEventListener('resize', applyPosition);
    try { appWindow.removeEventListener('pagehide', destroyMusicPlayer); } catch (_) {}
    try { window.removeEventListener('pagehide', destroyMusicPlayer); } catch (_) {}
    player?.remove();
  }
  // 页面卸载/切聊天导致脚本重载时，清掉 900ms 轮询、resize 监听与 DOM，避免多实例残留
  appWindow.addEventListener('pagehide', destroyMusicPlayer);
  if (window !== appWindow) window.addEventListener('pagehide', destroyMusicPlayer);
  appWindow[GLOBAL_KEY] = { destroy: destroyMusicPlayer };
  console.info('[暨阳音乐播放器] 已加载，等待手动播放。');
})();

// 暨阳正文：装饰已渲染的对白和对应楼层的场景，不改聊天原文、草稿或 MVU。
// API依据：SillyTavern 1.19.0 st-context.js；Tavern Helper 4.12.0 variables.d.ts。
(() => {
  'use strict';
  let host = window;
  try { if (window.top.document) host = window.top; } catch (_) {}
  const doc = host.document;
  const KEY = '__jyDialogue';
  const AVATAR_EVENT = 'jy-avatar-changed';
  host[KEY]?.destroy();
  // JY_SCENES_BEGIN
  const scenes = {"places":[["高二重点班教室",["八班","高二（8）班","高二(8)班","高三八班","高三教室","教学楼","教室"],"corridor"],["高二教师办公室（英语组）",["英语办公室","英语组","教师办公室"],"office"],["操场",["篮球场","跑道"],"sports"],["操场器材室",["操场器材室"],"equipment"],["音乐教室",["音乐教室"],"music"],["礼堂后台",["礼堂后台"],"arts"],["图书馆",["借还台","文学社长桌","旧书库"],"library"],["天台",["楼顶","天台铁门"],"roof"],["食堂",["小炒窗口","食堂后门"],"canteen"],["小花园",["鹅卵石路","花园长椅"],"garden"],["实验楼",["竞赛自习室","竞赛教室","物理实验室"],"lab"],["行政楼",["年级组会议室","家长接待室","校长室","校长办公室","教务处"],"admin"],["暨阳路校门口",["校门口","校门公交站","公交站","暨阳路"],"bus"],["雄风老商场",["雄风商场","老雄风","雄风"],"mall"],["KFC与正新鸡排",["肯德基","KFC","正新鸡排"],"kfc"],["青悦城",["无招牌咖啡馆","青悦城四楼"],"qing"],["遇见奶茶店",["遇见奶茶","遇见店"],"tea"],["晨光文具复印店",["晨光文具","复印店","文印店"],"copyshop"],["浣江步道",["浣江边","浦阳江","浦阳江边","河边步道","浣江路"],"river"],["老城生活圈",["老城窄巷","老城","艮塔公园","次坞打面"],"oldtown"],["西施故里与御江湾",["西施故里","御江湾"],"heritage"],["城东万风新天地",["万风新天地","万风"],"east"],["万达宝龙商圈",["万达广场","宝龙广场","万达","宝龙"],"wanda"],["老鹰山",["老鹰山步道","老鹰山山脚","听风亭","老鹰山观景台"],"mountain"],["暨阳站",["高铁站","暨阳火车站"],"station"]],"photos":{"office":["高二教师办公室（英语组）的场景照","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/office.webp"],"canteen":["食堂的场景照","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/canteen.webp"],"music":["音乐教室的场景照","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/music.webp"],"qing":["青悦城的场景照","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/qing.webp"],"mall":["雄风老商场的场景照","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/mall.webp"],"tea":["遇见奶茶店的场景照","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/tea.webp"],"heritage":["西施故里与御江湾的场景照","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/heritage.webp"],"admin":["行政楼的场景照","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/admin.webp"],"oldtown":["老城生活圈的场景照","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/oldtown.webp"],"river":["浣江步道的场景照","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/river.webp"],"station":["暨阳站的场景照","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/station.webp"],"equipment":["操场器材室的场景照","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/equipment.webp"],"garden":["小花园的场景照","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/garden.webp"],"lab":["实验楼的场景照","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/lab.webp"],"roof":["天台的场景照","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/roof.webp"],"east":["城东万风新天地的场景照","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/east.webp"],"wanda":["万达宝龙商圈的场景照","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/wanda.webp"],"kfc":["KFC与正新鸡排的场景照","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/kfc.webp"],"copyshop":["暑假午后的晨光文具复印店","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/copyshop.webp"],"arts":["艺术周彩排前从侧幕望向舞台","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/arts.webp"],"sports":["体育周开赛前的篮球场","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/sports.webp"],"mountain":["雨后老鹰山的听风亭与步道","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/mountain.webp"],"corridor":["雨后湿润的教学楼连廊","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/corridor.webp"],"library":["图书馆靠窗长桌，旧书上放着一张还书单","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/library.webp"],"bus":["傍晚亮起灯的校门公交站","https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@e450d24017cd3fed4bb069b3699ec8f589f32382/statusbar/scenes/bus.webp"]}};
  // JY_SCENES_END
  const normalizePlace = value => value.normalize('NFKC').replace(/\s+/gu, '').toLowerCase();
  const placeAliases = scenes.places.flatMap(([name, aliases, key]) =>
    [name, ...aliases].filter(Boolean).map(alias => [normalizePlace(alias), key])
  ).sort((a, b) => b[0].length - a[0].length);
  const scenery = new Set();
  const failedScenes = new WeakMap();
  const subscriptions = [];
  const defaults = {
    '苏晓樯': 'v2/avatars/xiaoqiang.png',
    '温书语': 'v2/avatars/shuyu.png',
    '沈幼楚': 'v2/avatars/youchu.png',
    '许念安': 'v2/avatars/nianan.png',
    '慕佳芊': 'v2/avatars/jiaqian.png',
    '陈芷汀': 'v2/avatars/zhiting.png',
    '虞淑婉': 'v1/avatars/shuwan.png',
    '吴臻臻': 'v2/avatars/wuzhenzhen.webp',
  };
  const reserved = new Set(['旁白', '系统', '状态', '状态栏', '选项', '规则', '内心独白']);
  // 模型偶尔会用称呼写标签，映射回标准角色名，才能命中同名头像缓存。
  const nameAliases = {
    '小天女': '苏晓樯', '书语': '温书语', '幼楚': '沈幼楚',
    '念安': '许念安', '安安': '许念安', '学习委员': '许念安',
    '吴班长': '吴臻臻',
    '佳芊': '慕佳芊', '慕老师': '慕佳芊', '英语老师': '慕佳芊',
    '芷汀': '陈芷汀', '虞校长': '虞淑婉', '校长': '虞淑婉', '淑婉': '虞淑婉',
  };
  const PLAYER_ALIASES = new Set(['主角', '玩家', 'user', '我', '你']);
  function canonicalName(name) {
    return Object.hasOwn(defaults, name) ? name : (nameAliases[name] || name);
  }
  const mounted = new Map();
  let timer = null;
  let stopped = false;
  const style = doc.createElement('style');
  style.dataset.jyDialogueStyle = '';
  style.textContent = `
    [data-jy-scene] { position:relative; display:block; overflow:hidden; isolation:isolate; margin:0 0 14px; height:clamp(92px, 18vw, 158px); border-radius:10px; background:#334945; }
    [data-jy-scene] img { display:block; width:100%; height:100%; object-fit:cover; margin:0; border:0; }
    [data-jy-scene] figcaption { position:absolute; inset:auto 0 0; padding:18px 12px 8px; color:#fff; background:linear-gradient(transparent,#172522d9); text-align:left; text-indent:0; font-size:.8em; }
    [data-jy-dialogue-source] { display:none!important; }
    [data-jy-dialogue-render] { display:block; }
    [data-jy-dialogue-row] { --jy-ink:#244c45; --jy-edge:#c7dcd4; display:flex; align-items:flex-start; gap:12px; margin:18px 0; max-width:100%; min-width:0; text-indent:0; text-align:left; line-height:1.8; }
    [data-jy-dialogue-row] * { box-sizing:border-box; }
    [data-jy-dialogue-row][data-player=true] { flex-direction:row-reverse; --jy-ink:#795137; --jy-edge:#e5cdb9; }
    [data-jy-dialogue-avatar] { flex:0 0 46px; width:46px; height:46px; position:relative; display:grid; place-items:center; overflow:hidden; border:1px solid var(--jy-edge); border-radius:50%; background:#e9f1ec; color:var(--jy-ink); font-size:19px; }
    [data-jy-dialogue-avatar] img { position:absolute; inset:0; width:100%; height:100%; object-fit:cover; margin:0; border:0; border-radius:inherit; }
    [data-jy-dialogue-bubble] { display:block; min-width:0; max-width:min(680px, calc(100% - 58px)); padding:11px 16px 13px; background:#f7faf7; border:1px solid var(--jy-edge); border-radius:4px 16px 16px; color:#263e38; overflow-wrap:anywhere; white-space:pre-wrap; font-size:1em; box-shadow:0 3px 10px #163f2910; }
    [data-player=true] [data-jy-dialogue-bubble] { background:#fff8f0; border-radius:16px 4px 16px 16px; }
    [data-jy-dialogue-name] { display:block; color:var(--jy-ink); font-size:.82em; font-weight:650; margin-bottom:3px; }
    [data-jy-dialogue-body] { display:block; }
    @media(max-width:480px) {
      [data-jy-dialogue-row] { gap:8px; margin:14px 0; }
      [data-jy-dialogue-avatar] { flex-basis:34px; width:34px; height:34px; font-size:16px; }
      [data-jy-dialogue-bubble] { max-width:calc(100% - 42px); padding:9px 11px; }
    }
  `;
  doc.head.append(style);

  function parseLine(raw) {
    const match = raw.trim().match(/^\{([^{}\n<>]{1,40})\}\s*「([^「」\n]+)」$/u);
    if (!match || reserved.has(match[1].trim())) return null;
    return { name: match[1].trim(), body: match[2] };
  }

  function safeSource(src) {
    return typeof src === 'string' && (/^data:image\/(?:png|jpeg|webp|gif);base64,[a-z0-9+/=]+$/i.test(src) || /^https?:\/\//i.test(src));
  }

  function avatarSources(name) {
    const sources = [];
    try {
      const cached = host.localStorage.getItem('jy-avatar:' + name);
      if (safeSource(cached)) sources.push(cached);
    } catch (_) {}
    if (Object.hasOwn(defaults, name)) {
      sources.push('https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@main/statusbar/' + defaults[name]);
      sources.push('https://raw.githubusercontent.com/YangChen-cn/jiyang-school-assets/main/statusbar/' + defaults[name]);
    }
    return sources;
  }

  function messageState(message) {
    try {
      const id = message?.getAttribute('mesid');
      const read = window.getVariables || host.TavernHelper?.getVariables;
      if (!id || !/^\d+$/.test(id) || typeof read !== 'function') return undefined;
      return read({ type: 'message', message_id: Number(id) })?.stat_data;
    } catch (_) { return undefined; }
  }

  function decorateScene(body, state) {
    const location = state?.世界?.当前位置;
    const label = typeof location === 'string' ? location.trim() : '';
    const value = normalizePlace(label);
    const match = placeAliases.find(([alias]) => value === alias)
      || placeAliases.find(([alias]) => alias.length >= 3 && value.includes(alias));
    const photo = match && scenes.photos[match[1]];
    const current = body.querySelector(':scope > [data-jy-scene]');
    if (current && photo && current.dataset.jyScene === match[1] && current.lastElementChild?.textContent === label) return;
    if (current) {
      current.remove();
      scenery.delete(current);
    }
    if (!photo || failedScenes.get(body) === match[1]) return;
    const figure = doc.createElement('figure');
    figure.dataset.jyScene = match[1];
    figure.contentEditable = 'false';
    const image = doc.createElement('img');
    image.alt = photo[0];
    image.loading = 'lazy';
    image.decoding = 'async';
    const fallback = photo[1].replace('https://cdn.jsdelivr.net/gh/YangChen-cn/jiyang-school-assets@', 'https://raw.githubusercontent.com/YangChen-cn/jiyang-school-assets/');
    image.addEventListener('error', () => {
      if (image.src !== fallback && figure.isConnected) {
        image.src = fallback;
        return;
      }
      failedScenes.set(body, match[1]);
      scenery.delete(figure);
      figure.remove();
    });
    image.src = photo[1];
    const caption = doc.createElement('figcaption');
    caption.textContent = label;
    figure.append(image, caption);
    body.prepend(figure);
    scenery.add(figure);
  }

  function playerNames(state) {
    const names = new Set(PLAYER_ALIASES);
    const name = state?.主角?.姓名;
    if (typeof name === 'string' && name.trim()) names.add(name.trim());
    try {
      const name = host.SillyTavern?.getContext()?.name1;
      if (typeof name === 'string' && name.trim()) names.add(name.trim());
    } catch (_) {}
    return names;
  }

  function paintAvatar(avatar, key) {
    const sources = avatarSources(key);
    // Keep failed-image fallbacks stable instead of retrying on every DOM change.
    const signature = JSON.stringify(sources);
    if (avatar.dataset.signature === signature) return;
    avatar.dataset.signature = signature;
    avatar.querySelector('img')?.remove();
    if (!sources.length) return;
    const img = doc.createElement('img');
    img.alt = '';
    img.decoding = 'async';
    // Let the browser paint decoded images even if the host copied the node
    // during rendering and its load handler did not carry over.
    let index = 0;
    img.onerror = () => {
      if (++index < sources.length) img.src = sources[index];
      else img.remove();
    };
    avatar.append(img);
    img.src = sources[0];
  }

  function makeRow(dialogue, names) {
    const row = doc.createElement('span');
    row.dataset.jyDialogueRow = '';
    row.dataset.speaker = dialogue.name;
    const avatar = doc.createElement('span');
    avatar.dataset.jyDialogueAvatar = '';
    avatar.setAttribute('aria-hidden', 'true');
    avatar.textContent = Array.from(dialogue.name)[0];
    const bubble = doc.createElement('span');
    bubble.dataset.jyDialogueBubble = '';
    const label = doc.createElement('span');
    label.dataset.jyDialogueName = '';
    label.textContent = dialogue.name;
    const body = doc.createElement('span');
    body.dataset.jyDialogueBody = '';
    body.textContent = '「' + dialogue.body + '」';
    bubble.append(label, body);
    row.append(avatar, bubble);
    refreshRow(row, names);
    return row;
  }

  function refreshRow(row, names) {
    const name = row.dataset.speaker;
    // A named NPC wins over a coincidentally identical persona name.
    const isPlayer = (!Object.hasOwn(defaults, name) || PLAYER_ALIASES.has(name)) && names.has(name);
    row.dataset.player = String(isPlayer);
    paintAvatar(row.querySelector('[data-jy-dialogue-avatar]'), isPlayer ? '主角' : canonicalName(name));
  }

  function decorate(p, names) {
    if (p.hasAttribute('data-jy-dialogue-mounted')) return;
    // Do not parse code, links, options, thought panels, status UI or arbitrary HTML.
    if (p.closest('details,pre,code,blockquote,table,li,[data-jy-dialogue-source]')) return;
    if ([...p.querySelectorAll('*')].some(n => !['BR', 'Q', 'EM', 'STRONG'].includes(n.tagName))) return;
    const lines = [];
    let line = [];
    function flush() { lines.push(line); line = []; }
    for (const node of p.childNodes) {
      if (node.nodeName === 'BR') flush();
      else if (node.nodeType === 3 && node.textContent.includes('\n')) {
        node.textContent.split('\n').forEach((part, i) => { if (i) flush(); line.push(doc.createTextNode(part)); });
      } else line.push(node.cloneNode(true));
    }
    flush();
    const dialogues = lines.map(nodes => parseLine(nodes.map(n => n.textContent).join('')));
    if (!dialogues.some(Boolean)) return;
    const source = doc.createElement('span');
    source.dataset.jyDialogueSource = '';
    source.hidden = true;
    const render = doc.createElement('span');
    render.dataset.jyDialogueRender = '';
    lines.forEach((nodes, i) => {
      if (dialogues[i]) render.append(makeRow(dialogues[i], names));
      else {
        const plain = doc.createElement('span');
        plain.append(...nodes);
        render.append(plain, doc.createElement('br'));
      }
    });
    source.append(...p.childNodes);
    p.append(source, render);
    p.dataset.jyDialogueMounted = '';
    mounted.set(p, source);
  }

  const observer = new host.MutationObserver(schedule);
  function scan() {
    if (stopped) return;
    observer.disconnect();
    try {
      for (const [p, source] of mounted) {
        if (!p.isConnected || source.parentNode !== p) {
          mounted.delete(p);
          p.removeAttribute('data-jy-dialogue-mounted');
        }
      }
      for (const figure of scenery) if (!figure.isConnected) scenery.delete(figure);
      doc.querySelectorAll('#chat .mes[is_user="false"] .mes_text').forEach(body => {
        const state = messageState(body.closest('.mes'));
        decorateScene(body, state);
        const names = playerNames(state);
        // Only ordinary prose paragraphs; no descent into another extension's panel.
        body.querySelectorAll(':scope > p, :scope > content > p, :scope > main > p').forEach(p => decorate(p, names));
        body.querySelectorAll('[data-jy-dialogue-row]').forEach(row => refreshRow(row, names));
      });
    } finally {
      if (!stopped) observer.observe(doc.querySelector('#chat') || doc.body, { childList: true, subtree: true, characterData: true });
    }
  }
  function schedule() {
    if (!stopped && timer === null) timer = host.setTimeout(() => { timer = null; scan(); }, 80);
  }
  function storageChanged(event) {
    if (event.key === null || event.key?.startsWith('jy-avatar:')) schedule();
  }
  function destroy() {
    if (stopped) return;
    stopped = true;
    observer.disconnect();
    host.clearTimeout(timer);
    host.removeEventListener(AVATAR_EVENT, schedule);
    host.removeEventListener('storage', storageChanged);
    window.removeEventListener('pagehide', destroy);
    for (const [p, source] of mounted) {
      if (source.parentNode === p) p.replaceChildren(...source.childNodes);
      p.removeAttribute('data-jy-dialogue-mounted');
    }
    mounted.clear();
    for (const sub of subscriptions) sub?.stop?.();
    for (const figure of scenery) figure.remove();
    scenery.clear();
    style.remove();
    if (host[KEY]?.destroy === destroy) delete host[KEY];
  }
  if (typeof eventOn === 'function') {
    for (const event of ['message_received', 'message_updated', 'message_swiped', 'chat_id_changed', 'mag_variable_update_ended']) {
      subscriptions.push(eventOn(event, schedule));
    }
  }
  host.addEventListener(AVATAR_EVENT, schedule);
  host.addEventListener('storage', storageChanged);
  window.addEventListener('pagehide', destroy, { once: true });
  function debug() {
    let keys = [];
    try {
      keys = Object.keys(host.localStorage).filter((key) => key.startsWith('jy-avatar:')).map((key) => ({ key, length: String(host.localStorage.getItem(key) || '').length }));
    } catch (_) {}
    const rows = [...doc.querySelectorAll('[data-jy-dialogue-row]')].map((row) => {
      const avatar = row.querySelector('[data-jy-dialogue-avatar]');
      const image = avatar?.querySelector('img');
      return { speaker: row.dataset.speaker, player: row.dataset.player, signature: (avatar?.dataset.signature || '').slice(0, 48), src: (image?.src || '').slice(0, 40), loaded: image ? image.complete && image.naturalWidth > 0 : false };
    });
    return { top: host === host.top, keys, rows };
  }
  host[KEY] = { destroy, debug };
  scan();
})();

