---
（当前变量快照：仅供阅读；禁止在正文、规划或分析中复述，禁止把它转写成 YAML 列表输出。）
<status_current_variable>
<%_ {
const snapshot = {...getvar('stat_data', { defaults: {} })};
delete snapshot.凌知夏;
if (snapshot.剧情) {
  snapshot.剧情 = {...snapshot.剧情};
  delete snapshot.剧情.当日关系增量;
  delete snapshot.剧情.重大情感申请;
  delete snapshot.剧情.已结算重大情感事件;
}
_%>
<%- JSON.stringify(snapshot) %>
<%_ } _%>
</status_current_variable>

@@generate_before
@@always_enabled
<%_
if (typeof charLoreBook === 'string' && charLoreBook === world_info.world) {
// Shared by the prompt, calendar and MVU. Dates are in the story's local calendar.
function campusDate(value) {
  const date = typeof value === 'string' ? value.replaceAll('/', '-') : '';
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return '';
  const parsed = new Date(date + 'T12:00:00Z');
  return Number.isFinite(parsed.getTime()) && parsed.toISOString().slice(0, 10) === date ? date : '';
}

function campusYear(value) {
  const year = Number(value);
  return Number.isInteger(year) && year >= 1000 && year <= 9900 ? year : 2020;
}

function campusAnchor(edge, year) {
  return edge ? `${year + edge[0]}-${edge[1]}` : '';
}

function campusPeriod(periods, date, year, academic) {
  if (academic === '已毕业') return periods.find(period => period.id === '已毕业');
  date = campusDate(date);
  if (!date) return null;
  return periods.find(period => date >= campusAnchor(period.start, year) && date <= campusAnchor(period.end, year)) || null;
}

function campusAgeAt(birthday, date) {
  const birth = campusDate(birthday);
  const now = campusDate(date);
  if (!birth || !now || birth > now) return null;
  return Number(now.slice(0, 4)) - Number(birth.slice(0, 4)) - Number(now.slice(5) < birth.slice(5));
}

function campusPlayerClass(identity, academic) {
  // Keep custom identities, transfers and class changes from the story.
  if (identity !== '暨阳中学高二重点班学生' && identity !== '暨阳中学高三重点班学生') return identity;
  if (academic === '已毕业') return '暨阳中学毕业生';
  if (academic === '高三上' || academic === '高三下') return '暨阳中学高三重点班学生';
  return identity;
}

// Shared by the message writeback and the read-only preview of old snapshots.
function normalizeCampus(value, today, activityIds) {
  const now = campusDate(today);
  const list = posts => Array.isArray(posts) ? posts.filter(post =>
    post && typeof post.标识 === 'string' && post.标识 && typeof post.标题 === 'string' && typeof post.摘要 === 'string'
  ) : [];
  const isNotice = post => post.渠道 === '公告' || (post.渠道 === '班群' &&
    /老师|班主任|班长|班委|吴臻臻|慕佳芊|教务|教导处|年级组|体育组|校方|学生会|团委|学校|组织者|负责人/.test(post.来源 || ''));
  const knownActivity = post => isNotice(post) && activityIds.includes(post.活动标识);
  const dates = post => [campusDate(post.确认开始), campusDate(post.确认结束)];
  const scheduleRecord = (status, start, end) => {
    if (start && end && start <= end) return {状态: status, 开始: start, 结束: end};
    if (status === '已撤销' || status === '已结束') return {状态: status};
    return null;
  };
  const schedule = {};
  for (const id of activityIds) {
    const record = value?.日程?.[id];
    if (!['已确认', '已结束', '已撤销'].includes(record?.状态)) continue;
    const normalized = scheduleRecord(record.状态, campusDate(record.开始), campusDate(record.结束));
    if (normalized) {
      if (normalized.状态 === '已确认' && now && normalized.结束 < now) normalized.状态 = '已结束';
      schedule[id] = normalized;
    }
  }

  const legacy = list(value?.消息);
  // Only dated official notices, or explicit withdrawals of those notices,
  // may be promoted from the old mixed array.
  const legacyNotice = post => {
    const [start, end] = dates(post);
    return knownActivity(post) && (scheduleRecord('已确认', start, end) ||
      post.状态 === '已撤销' || (post.渠道 === '公告' && post.状态 === '已结束'));
  };
  const datedLegacy = legacy.filter(legacyNotice);
  const proposed = list(value?.有效公告);
  const notices = [...datedLegacy, ...proposed.filter(isNotice)];
  const seenPosts = new Set();
  const seenActivities = new Set();
  const active = [];
  const soon = now ? Date.parse(now) + 7 * 86400000 : 0;
  for (let i = notices.length - 1; i >= 0; i--) {
    const post = notices[i];
    const id = knownActivity(post) ? post.活动标识 : null;
    if (seenPosts.has(post.标识) || (id && seenActivities.has(id))) continue;
    seenPosts.add(post.标识);
    if (id) seenActivities.add(id);
    const [start, end] = dates(post);
    const dated = start && end && start <= end;
    const existing = id ? schedule[id] : null;
    const result = post.状态 === '已撤销' ? '已撤销'
      : post.状态 === '已结束' || (dated && now && end < now) ? '已结束' : '已确认';
    if (result === '已确认' && !dated && ['已撤销', '已结束'].includes(existing?.状态)) continue;
    if (id) {
      const record = scheduleRecord(result, dated ? start : existing?.开始, dated ? end : existing?.结束);
      if (record) schedule[id] = record;
    }
    if (result === '已确认') active.push({post, i, near: Boolean(id && now && dated && Date.parse(start) <= soon)});
  }
  const announcements = active.sort((a, b) => Number(b.near) - Number(a.near) || b.i - a.i)
    .slice(0, 3).sort((a, b) => a.i - b.i).map(({post}) => post);
  const seenDynamics = new Set();
  const feed = [...legacy.filter(post => !legacyNotice(post)), ...proposed.filter(post => !isNotice(post)), ...list(value?.动态流)]
    .reverse().filter(post => {
      if (seenDynamics.has(post.标识) || seenPosts.has(post.标识)) return false;
      seenDynamics.add(post.标识);
      return true;
    }).slice(0, 6).reverse().map(post => {
      const {活动标识, 确认开始, 确认结束, ...dynamic} = post;
      return dynamic;
    });
  return {有效公告: announcements, 动态流: feed, 日程: schedule};
}

function campusEventPhase(activity, calendar, date, year) {
  const confirmed = calendar?.[activity.id];
  if (confirmed?.状态 === '已撤销') return {kind: 'cancelled', label: '正式通知已撤销。仅在被问及时回应通知与已发生的准备。'};
  if (confirmed?.状态 === '已结束') return {kind: 'after', label: '活动已结束。仅承接实际安排、公开结果与已发生的经历。'};

  const start = confirmed?.开始 || campusAnchor(activity.start, year);
  const end = confirmed?.结束 || campusAnchor(activity.end, year);
  if (!start) return {kind: 'undated', label: '日期未确认。按当年农历与已知安排回答，先核对日期。'};
  const range = start === end ? start : `${start} 至 ${end}`;
  const window = `${confirmed ? '正式日期' : '预计窗口'} ${range}`;
  if (date < start) return {kind: 'before', label: `${window}，尚未开始。只写询问与筹备。`};
  if (date > end) return {kind: 'after', label: `${window}，日期已过。只承接已经发生的事。`};
  if (confirmed) return {kind: 'live', label: `${window}。按当前时段、场所及实际安排判断是否正在进行。`};
  if (activity.id === 'summer-practice') return {kind: 'window', label: `${window}。可询问工读或家教机会，岗位和排班现场确认。`};
  return {kind: 'window', label: `${window}。可查通知或筹备，活动是否开始以当前现场为准。`};
}

function campusRoutes(periods, state) {
  const rawDate = state.世界?.日期;
  const hasDate = rawDate != null && rawDate !== '';
  const year = campusYear(state.世界?.起始年份);
  const date = hasDate ? campusDate(rawDate) : `${year}-09-01`;
  const calendarPeriod = campusPeriod(periods, date, year);
  const period = state.剧情?.学期 === '已毕业' ? campusPeriod(periods, date, year, '已毕业') : calendarPeriod;
  // The class can still hold its graduation gathering after a confirmed early ceremony.
  const activities = period?.id === '已毕业' && calendarPeriod?.id === '高三下'
    ? calendarPeriod.activities.filter(activity => activity.id === 'graduation-night') : period?.activities || [];
  const calendar = normalizeCampus(state.校园, date, periods.flatMap(p => (p.activities || []).map(a => a.id))).日程;
  const phases = Object.fromEntries(activities.map(a => [a.id, campusEventPhase(a, calendar, date, year)]));
  const location = state.世界?.当前位置;
  const focus = state.剧情?.校园活动;
  const active = hasDate ? activities.filter(a => ['window', 'live'].includes(phases[a.id].kind)) : [];
  const named = focus && active.find(a => (a.name === focus || a.id === focus));
  const onSite = active.filter(a => phases[a.id].kind === 'live' && a.routePlaces?.includes(location));
  return {period, phases, activate: named?.entry || (onSite.length === 1 ? onSite[0].entry : '')};
}

const jyPeriods = [{"id":"高二上","start":[0,"08-01"],"end":[1,"02-20"],"activities":[{"id":"opening","name":"开学周","start":[0,"09-01"],"end":[0,"09-07"],"routePlaces":["高二重点班教室","重点班教室"],"entry":"事件_开学周"},{"id":"national","name":"国庆假期","start":[0,"10-01"],"end":[0,"10-07"],"entry":"国庆假期"},{"id":"sports","name":"体育周","start":[0,"10-11"],"end":[0,"10-31"],"routePlaces":["操场","暨阳中学操场","操场器材室"],"entry":"体育周"},{"id":"midterm","name":"期中考试","start":[0,"11-01"],"end":[0,"11-10"],"entry":"期中考试"},{"id":"hike","name":"远足","start":[0,"11-11"],"end":[0,"11-30"],"routePlaces":["老鹰山远足集合点","老鹰山远足签到点"],"entry":"远足"},{"id":"new-year","name":"元旦","start":[1,"01-01"],"end":[1,"01-01"],"entry":"事件_元旦"},{"id":"winter","name":"寒假","start":[1,"01-21"],"end":[1,"02-20"],"entry":"寒假"},{"id":"spring-festival","name":"春节","start":null,"end":null,"entry":"寒假"}],"notice":"报到、日常课业与班级分工逐渐稳定。开学前以返校准备与学校公开安排为主。"},{"id":"高二下","start":[1,"02-21"],"end":[1,"06-30"],"activities":[{"id":"arts","name":"艺术周","start":[1,"04-01"],"end":[1,"04-30"],"routePlaces":["音乐教室","礼堂后台","大礼堂"],"entry":"艺术周"},{"id":"study-trip","name":"高校研学实践","start":[1,"05-10"],"end":[1,"05-20"],"routePlaces":["浙江大学校园","浙江大学紫金港校区","浙江大学之江校区"],"entry":"高校研学实践"}],"notice":"春季返校后恢复课业。排练、训练和校外集体活动都按各自的通知与报名安排。"},{"id":"暑假","start":[1,"07-01"],"end":[1,"08-31"],"activities":[{"id":"summer-practice","name":"暑期工读与家教实践","start":[1,"07-01"],"end":[1,"08-15"],"routePlaces":["遇见奶茶店"],"entry":"暑期工读与家教实践"}],"notice":"学校按假期开放，查看值班与借阅通知。城内家庭、补课、店铺排班各有安排。"},{"id":"高三上","start":[1,"09-01"],"end":[2,"02-20"],"activities":[{"id":"coming-of-age","name":"十八岁成人礼与首考誓师","start":[1,"10-20"],"end":[1,"11-10"],"routePlaces":["成人门","成人礼签到处"],"entry":"十八岁成人礼与首考誓师"}],"notice":"年级可能换教室并公布备考安排。社团与班务的交接由实际负责人确认。"},{"id":"高三下","start":[2,"02-21"],"end":[2,"06-30"],"activities":[{"id":"graduation-night","name":"最后一课与毕业散伙狂欢夜","start":[2,"06-01"],"end":[2,"06-20"],"routePlaces":["青悦城大酒楼宴会厅"],"entry":"最后一课与毕业散伙狂欢夜"}],"notice":"复习、报考与毕业手续并行。聚会、录取和去向分别等公开通知或本人确认。"},{"id":"已毕业","start":[2,"07-01"],"end":[99,"12-31"],"notice":"返校需要按访客安排登记。同学各有去向，熟悉的地点也会继续日常营业。","activities":[]}];
const jyState = getvar('stat_data', { defaults: {} }) || {};
const jyRoute = campusRoutes(jyPeriods, jyState);
define('jyCampusEvents', jyRoute.phases);
if (jyRoute.activate) await activewi(charLoreBook, jyRoute.activate, true);
if (jyRoute.period) {
_%>
当前生活阶段：<%= jyRoute.period.id %>。<%= jyRoute.period.notice %>
人物档案中的年龄、年级和教职是开局资料。后续称谓按实际年级、升学、教职变动和毕业经历；生日未知时沿用已确认年龄或使用阶段称呼。亲友到场和年龄均不能从成年仪式本身推定。
个人邀约、家长是否到场、信件、陪同与去向，以各自实际安排、已发生的事和双方选择为准。校园动态涉及既有剧情时，只引用已经公开的事实；论坛仅供状态栏展示，不能默认其他角色都知道论坛里的消息。
<%_ } } _%>
